def parse_cond(tokens, pos, env):
    """Parse conditional expressions: a ? b : c"""
    expr = parse_or(tokens, pos, env)

    if pos[0] < len(tokens) and tokens[pos[0]][0] == 'COND':
        pos[0] += 1  # consume '?'
        then_expr = parse_or(tokens, pos, env)
        if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'COLON':
