    expr = parse_and(tokens, pos, env)

    while pos[0] < len(tokens) and tokens[pos[0]][0] == 'OR':
        pos[0] += 1  # consume '||'
        right = parse_and(tokens, pos, env)
        # Short-circuit: if left is truthy, result is 1
        if expr:
            expr = 1
        else:
            expr = right
        if expr:
            expr = 1
        else:
            expr = 0

    return expr


def parse_and(tokens, pos, env):
