    expr = parse_comparison(tokens, pos, env)

    while pos[0] < len(tokens) and tokens[pos[0]][0] == 'AND':
        pos[0] += 1  # consume '&&'
        right = parse_comparison(tokens, pos, env)
        # Short-circuit: if left is falsy, result is 0
        if not expr:
            expr = 0
        else:
            expr = right
        if not expr:
            expr = 0
        else:
            expr = 1

