    if pos[0] < len(tokens) and tokens[pos[0]][0] in ('EQ', 'NEQ', 'LT', 'LE', 'GT', 'GE'):
        op = tokens[pos[0]][0]
        pos[0] += 1
        right = parse_additive(tokens, pos, env)

        # Check for another comparison operator immediately after
        if pos[0] < len(tokens) and tokens[pos[0]][0] in ('EQ', 'NEQ', 'LT', 'LE', 'GT', 'GE'):
            raise SyntaxError("Chained comparisons are not allowed")

        if op == 'EQ':
            expr = 1 if expr == right else 0
        elif op == 'NEQ':
            expr = 1 if expr != right else 0
        elif op == 'LT':
            expr = 1 if expr < right else 0
        elif op == 'LE':
            expr = 1 if expr <= right else 0
        elif op == 'GT':
            expr = 1 if expr > right else 0
        elif op == 'GE':
            expr = 1 if expr >= right else 0

