    """Parse *, /, % expressions"""
    expr = parse_unary(tokens, pos, env)

    while pos[0] < len(tokens) and tokens[pos[0]][0] in ('MUL', 'DIV', 'MOD'):
        op = tokens[pos[0]][0]
        pos[0] += 1
        right = parse_unary(tokens, pos, env)

        if op == 'MUL':
            expr = expr * right
        elif op == 'DIV':
