def parse_unary(tokens, pos, env):
    """Parse unary +, -, !"""
    if pos[0] < len(tokens) and tokens[pos[0]][0] in ('SUB', 'ADD', 'NOT'):
        op = tokens[pos[0]][0]
        pos[0] += 1
        expr = parse_unary(tokens, pos, env)

        if op == 'SUB':
            expr = -expr
        elif op == 'ADD':
            expr = expr
        else:  # NOT
