        expr = parse_power(tokens, pos, env)

    return expr


def parse_power(tokens, pos, env):
    """Parse ^ expressions (right-associative)"""
    left = parse_unary_minus(tokens, pos, env)

    if pos[0] < len(tokens) and tokens[pos[0]][0] == 'POW':
        pos[0] += 1
        right = parse_power(tokens, pos, env)
        return left ** right

    return left


def parse_unary_minus(tokens, pos, env):
    """Parse unary minus for power expressions: -2^2 is -4"""
    if pos[0] < len(tokens) and tokens[pos[0]][0] == 'SUB':
        pos[0] += 1
        expr = parse_unary_minus(tokens, pos, env)
        return -expr

    return parse_atom(tokens, pos, env)


def parse_atom(tokens, pos, env):
