            result = max(args)
        elif func_name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly one argument")
            result = abs(args[0])
        else:
            raise NameError(f"Unknown function: {func_name}")

        return result

    if token[0] == 'LPAREN':
        pos[0] += 1
        expr = parse_cond(tokens, pos, env)
        if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'RPAREN':
            raise SyntaxError("Expected ')' after expression")
        pos[0] += 1  # consume ')'
        return expr

    # Check for lone =, &, |
    if token[0] in ('ADD', 'SUB', 'MUL', 'DIV', 'MOD', 'POW', 'EQ', 'NEQ', 'LT', 'LE', 'GT', 'GE', 'AND', 'OR', 'NOT', 'COND', 'COLON'):
        raise SyntaxError(f"Unexpected token: {token[1]}")

