    if s_count != 1:
        raise ValueError(f"Expected exactly one start 'S', found {s_count}")
    if e_count != 1:
        raise ValueError(f"Expected exactly one end 'E', found {e_count}")

    # Check letter occurrences
    for letter, positions in letter_positions.items():
        if len(positions) != 2:
            raise ValueError(f"Letter '{letter}' appears {len(positions)} times, expected 2")

    # Find start and end positions
    start_pos = None
    end_pos = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    # Build teleport map
    teleport_map = {}
    for letter, positions in letter_positions.items():
        p1, p2 = positions
        teleport_map[p1] = p2
        teleport_map[p2] = p1

    # Directions: D, L, R, U (in lexicographic order for tie-breaking)
    directions = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('U', -1, 0)
    ]

    def get_cell_cost(pos):
        i, j = pos
        ch = grid[i][j]
        if ch == 'S' or ch == 'E' or ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1
        else:
            raise ValueError(f"Invalid cell type at {pos}")

    # Dijkstra's algorithm with state = (row, col)
    # Priority queue: (total_cost, path_string, row, col)
    # We want lexicographically smallest path among minimum cost paths

    # Use a dictionary to track best (cost, path) for each position
    best = {}

    # Priority queue: (cost, path, row, col)
    start_cost = get_cell_cost(start_pos)
    start_path = ""
    queue = [(start_cost, start_path, start_pos[0], start_pos[1])]
    best[start_pos] = (start_cost, start_path)

    while queue:
        cost, path, r, c = heapq.heappop(queue)

        # Skip if we've found a better way to this position
        if (r, c) in best and best[(r, c)] < (cost, path):
            continue

        # Check if we reached the end
        if (r, c) == end_pos:
            return (cost, path)

        # Skip if we already have a better path to this position
        if (r, c) in best and best[(r, c)][0] < cost:
            continue
        if (r, c) in best and best[(r, c)][0] == cost and best[(r, c)][1] < path:
            continue

        # Generate neighbors
        # First, normal moves
        for move, dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '#':
                move_cost = get_cell_cost((nr, nc))
                new_cost = cost + move_cost
                new_path = path + move

                # Check if this is better than what we have
                if (nr, nc) not in best or \
                   (new_cost, new_path) < best[(nr, nc)]:
                    best[(nr, nc)] = (new_cost, new_path)
                    heapq.heappush(queue, (new_cost, new_path, nr, nc))

        # Teleport move (only if current cell is a teleport pad)
        if (r, c) in teleport_map:
            nr, nc = teleport_map[(r, c)]
            move_cost = 2  # Teleport costs 2
            new_cost = cost + move_cost
            new_path = path + 'T'

            # Check if this is better than what we have
            if (nr, nc) not in best or \
               (new_cost, new_path) < best[(nr, nc)]:
                best[(nr, nc)] = (new_cost, new_path)
                heapq.heappush(queue, (new_cost, new_path, nr, nc))

    # If we exit the loop without finding end_pos, it's unreachable
    return None
