    """Resolve interpolation references in a value."""
    result = []
    i = 0
    while i < len(value):
        if i + 1 < len(value) and value[i:i+2] == '$$':
            result.append('$')
            i += 2
        elif value[i] == '$' and i + 1 < len(value) and value[i+1] == '{':
            # Find closing brace
            j = i + 2
            depth = 1
            while j < len(value) and depth > 0:
                if value[j] == '{':
                    depth += 1
                elif value[j] == '}':
                    depth -= 1
                j += 1

            if depth > 0:
                # Unclosed brace, treat as literal
                result.append(value[i])
                i += 1
                continue

            ref = value[i+2:j-1]

            # Parse reference
            if ':' in ref:
                parts = ref.split(':', 1)
                ref_section, ref_key = parts[0].strip(), parts[1].strip()
            else:
                ref_section, ref_key = section, ref.strip()

            # Check if reference exists
            if ref_section not in data or ref_key not in data[ref_section]:
                raise ValueError(f"Undefined reference: {ref}")

            # Check for cycles
            ref_tuple = (ref_section, ref_key)
            if ref_tuple in visited:
                raise ValueError(f"cycle detected in interpolation: {ref}")

            # Resolve recursively
            visited_copy = visited | {ref_tuple}
            resolved = resolve_value(data, ref_section, ref_key, data[ref_section][ref_key], visited_copy)
            result.append(resolved)
            i = j
        else:
            result.append(value[i])
