import re
from typing import List, Optional, Tuple, Union


class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

        # Validate no leading zeros in numeric parts
        if (major != 0 and str(major).startswith('0')) or \
           (minor != 0 and str(minor).startswith('0')) or \
           (patch != 0 and str(patch).startswith('0')):
            raise ValueError("Leading zeros in numeric parts are not allowed")

        # Validate prerelease identifiers if present
        if prerelease is not None:
            if not re.match(r'^[0-9A-Za-z-]+$', prerelease):
                raise ValueError("Invalid prerelease identifier")
            # Check for leading zeros in numeric identifiers
            for part in prerelease.split('.'):
                if part == '':
                    raise ValueError("Empty prerelease identifier")
                if re.match(r'^[0-9]+$', part) and len(part) > 1 and part[0] == '0':
                    raise ValueError("Numeric prerelease identifiers cannot have leading zeros")

        # Validate build metadata if present
        if build is not None:
            if not re.match(r'^[0-9A-Za-z-]+$', build):
                raise ValueError("Invalid build metadata identifier")

    def __repr__(self):
        return f"Version({self.major}, {self.minor}, {self.patch}, prerelease={self.prerelease}, build={self.build})"

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented

        # Compare major, minor, patch
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Now compare prerelease
        # If both have no prerelease, they're equal at this level
        if self.prerelease is None and other.prerelease is None:
            return False
        # If self has no prerelease but other does, self is greater (release > prerelease)
        if self.prerelease is None:
            return False
        # If self has prerelease but other doesn't, self is less
        if other.prerelease is None:
            return True

        # Both have prerelease, compare lexicographically by parts
        self_parts = self.prerelease.split('.')
        other_parts = other.prerelease.split('.')

        for i in range(min(len(self_parts), len(other_parts))):
            self_part = self_parts[i]
            other_part = other_parts[i]

            # Check if both are numeric
            self_numeric = re.match(r'^[0-9]+$', self_part)
            other_numeric = re.match(r'^[0-9]+$', other_part)

            if self_numeric and other_numeric:
                # Compare numerically
                if int(self_part) != int(other_part):
                    return int(self_part) < int(other_part)
            elif self_numeric:
                # Numeric < alphanumeric
                return True
            elif other_numeric:
                # Alphanumeric > numeric
                return False
            else:
                # Both alphanumeric, compare lexicographically
                if self_part != other_part:
                    return self_part < other_part

        # If all compared parts are equal, shorter list is smaller
        return len(self_parts) < len(other_parts)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return not (self < other)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))


def parse(v: str) -> Version:
    """Parse a semantic version string."""
    if not isinstance(v, str):
        raise ValueError("Version must be a string")

    v = v.strip()

    # Remove leading 'v' or '='
    if v.startswith('v') or v.startswith('='):
        v = v[1:].strip()

    # Pattern for semantic version
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-]+)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-]+))*))?(?:\+([0-9A-Za-z-]+))?$'

    match = re.match(pattern, v)
    if not match:
        raise ValueError(f"Invalid semantic version: {v}")

    major, minor, patch, prerelease, build = match.groups()

    return Version(int(major), int(minor), int(patch), prerelease, build)


def parse_partial_version(v: str) -> Tuple[int, int, int, Optional[str]]:
    """Parse a partial version string (e.g., '1', '1.2', '1.2.x', '1.2.*')."""
    v = v.strip()

    # Handle X-ranges
    if v.lower() == 'x':
        return (0, 0, 0, None)

    parts = v.split('.')

    major = 0
    minor = 0
    patch = 0
    prerelease = None

    # Parse major
    if parts[0].lower() == 'x':
        major = 0
    else:
        try:
            major = int(parts[0])
            if str(major).startswith('0') and major != 0:
                raise ValueError("Leading zeros in numeric parts are not allowed")
        except ValueError:
            raise ValueError(f"Invalid major version: {parts[0]}")

    # Parse minor
    if len(parts) > 1:
        if parts[1].lower() == 'x':
            minor = 0
        else:
            try:
                minor = int(parts[1])
                if str(minor).startswith('0') and minor != 0:
                    raise ValueError("Leading zeros in numeric parts are not allowed")
            except ValueError:
                raise ValueError(f"Invalid minor version: {parts[1]}")

    # Parse patch
