    echo "Usage: $0 [-d DELIM] [-s] COLUMN [FILE]" >&2
    exit 1
fi

# Read entire input
if [[ -n "$FILE" ]]; then
    CONTENT=$(cat "$FILE")
else
    CONTENT=$(cat)
fi

# Check for unterminated quotes
# Count quotes in content - if odd, there's an unterminated quote
QUOTE_COUNT=$(printf '%s' "$CONTENT" | tr -cd '"' | wc -c)
if ((QUOTE_COUNT % 2 != 0)); then
    echo "Error: unterminated quote" >&2
    exit 4
fi

# Determine column index
if [[ "$COLUMN" =~ ^#[0-9]+$ ]]; then
    COL_IDX="${COLUMN#\#}"
else
    # Extract header line (first line)
    HEADER_LINE=$(printf '%s' "$CONTENT" | awk -v RS='\r\n|\n|\r' 'NR==1 {print; exit}')

    # Use awk to parse CSV header and find column index
    COL_IDX=$(awk -v delim="$DELIM" -v colname="$COLUMN" '
    BEGIN {
        n = 0
    }
    {
        line = $0
        # Remove trailing \r if present
        gsub(/\r$/, "", line)

        # Parse CSV fields
        delete fields
        n = 0
        in_quote = 0
        field = ""

        for (i = 1; i <= length(line); i++) {
            c = substr(line, i, 1)

            if (in_quote) {
                if (c == "\"") {
                    if (substr(line, i+1, 1) == "\"") {
                        field = field "\""
                        i++
                    } else {
                        in_quote = 0
                    }
                } else {
                    field = field c
                }
            } else {
                if (c == "\"") {
                    in_quote = 1
                } else if (c == delim) {
                    n++
                    fields[n] = field
                    field = ""
                } else {
                    field = field c
                }
            }
        }
        n++
        fields[n] = field

        # Find column index
        for (i = 1; i <= n; i++) {
            if (fields[i] == colname) {
                print i
                exit
            }
        }
        print "0"  # Not found
    }
    ' <<< "$HEADER_LINE")

    if [[ "$COL_IDX" == "0" ]]; then
        echo "Error: column '$COLUMN' not found" >&2
        exit 3
    fi
fi

# Process CSV data
if [[ $SUMMARY -eq 0 ]]; then
    # Print values
    awk -v delim="$DELIM" -v col_idx="$COL_IDX" '
    BEGIN {
        RS = "\r\n|\n|\r"
        in_quote = 0
        field = ""
        n = 0
        row = 0
        header_parsed = 0
    }
    {
        line = $0
        # Remove trailing \r if present
        gsub(/\r$/, "", line)

        if (!header_parsed) {
            header_parsed = 1
            next
        }

        # Parse CSV fields
        delete fields
        n = 0
        in_quote = 0
        field = ""

        for (i = 1; i <= length(line); i++) {
            c = substr(line, i, 1)

            if (in_quote) {
                if (c == "\"") {
                    if (substr(line, i+1, 1) == "\"") {
                        field = field "\""
                        i++
                    } else {
                        in_quote = 0
                    }
                } else {
                    field = field c
                }
            } else {
                if (c == "\"") {
                    in_quote = 1
                } else if (c == delim) {
                    n++
                    fields[n] = field
                    field = ""
                } else {
                    field = field c
                }
            }
        }
        n++
        fields[n] = field

        # Output the requested column value
        if (col_idx <= n) {
            val = fields[col_idx]
        } else {
            val = ""
        }

        # Replace actual newlines with literal \n for output
        gsub(/\n/, "\\n", val)
        print val
    }
    ' <<< "$CONTENT"
else
    # Summary mode: count, sum, min, max
    awk -v delim="$DELIM" -v col_idx="$COL_IDX" '
    BEGIN {
        count = 0
        sum = 0
        min = ""
        max = ""
        in_quote = 0
        field = ""
        n = 0
