    }
    {
        line = $0
        # Remove trailing \r if present
        gsub(/\r$/, "", line)

        if (!header_parsed) {
            header_parsed = 1
            next
        }

        # Parse CSV fields
        delete fields
        n = 0
        in_quote = 0
