        for (i = 1; i <= length(line); i++) {
            c = substr(line, i, 1)

            if (in_quote) {
                if (c == "\"") {
                    if (substr(line, i+1, 1) == "\"") {
                        field = field "\""
                        i++
                    } else {
                        in_quote = 0
                    }
                } else {
                    field = field c
                }
            } else {
                if (c == "\"") {
