                } else if (c == delim) {
                    n++
                    fields[n] = field
                    field = ""
                } else {
                    field = field c
                }
            }
        }
        n++
        fields[n] = field

        # Get the requested column value
        if (col_idx <= n) {
            val = fields[col_idx]
        } else {
            val = ""
        }

        # Check if numeric (integer or decimal with optional sign)
        if (val ~ /^[-+]?([0-9]+\.?[0-9]*|[0-9]*\.?[0-9]+)$/) {
            num = val + 0
            count++
            sum += num
            if (min == "" || num < min) min = num
            if (max == "" || num > max) max = num
        }
    }
    END {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min, max
        }
    }
    ' <<< "$CONTENT"
fi
